:root {
  --card-bg: #f7f0e2;
  --card-border: #8b6f3e;
  --header-bg: #3b2a14;
  --header-text: #f2dfa7;
  --accent-gold: #c9963a;
  --label-text: #6b4e21;
  --body-text: #2e1f0d;
  --meta-key-color: #8b6f3e;
  --panel-bg: #ece2cc;
  --panel-border: #c4a96b;
  --tag-sedative-bg: #6b4e8a;
  --tag-sedative-text: #f0e6ff;
  --tag-immune-bg: #2e6b3e;
  --tag-immune-text: #e6ffe8;
  --tag-antiviral-bg: #7a2e2e;
  --tag-antiviral-text: #ffe6e6;
  --tag-tonic-bg: #2e5a6b;
  --tag-tonic-text: #e6f8ff;
  --footer-bg: #3b2a14;
  --footer-text: #f2dfa7;
  --bar-filled: #c9963a;
  --bar-empty: #6b4e21;
  --warn-color: #d4831a;
  --dots-color: #c4a96b;
}

article.formula-card {
  width: 480px;
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  overflow: hidden;
  font-size: 13px;
  color: var(--body-text);
}

.card-header {
  background-color: var(--header-bg);
  color: var(--header-text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-bottom: 3px solid var(--accent-gold);
}

.card-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-gold);
  border: 1px solid var(--accent-gold);
  padding: 2px 7px;
  border-radius: 2px;
}

.card-title {
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 1px;
  margin: 0;
  color: var(--header-text);
}

.card-number {
  font-size: 12px;
  font-weight: 600;
  color: var(--accent-gold);
  letter-spacing: 1px;
}

.formula-body {
  display: flex;
  gap: 0;
}

.formula-meta {
  width: 175px;
  flex-shrink: 0;
  padding: 12px 14px;
  border-right: 1px solid var(--panel-border);
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.meta-row {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.meta-key {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--meta-key-color);
}

.meta-val {
  font-size: 13px;
  font-weight: 600;
  color: var(--body-text);
}

.ingredients-panel {
  flex: 1;
  background-color: var(--panel-bg);
  padding: 10px 14px;
}

.panel-heading {
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--label-text);
  margin: 0 0 8px 0;
  border-bottom: 1px solid var(--panel-border);
  padding-bottom: 4px;
}

.ingredient-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ingredient-item {
  display: flex;
  align-items: center;
  gap: 5px;
}

.herb-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--body-text);
  white-space: nowrap;
  min-width: 90px;
}

.herb-dots {
  flex: 1;
  border-bottom: 1px dotted var(--dots-color);
  height: 0;
  margin-bottom: 2px;
}

.herb-qty {
  font-size: 12px;
  font-weight: 700;
  color: var(--label-text);
  white-space: nowrap;
}

.herb-tag {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 2px 6px;
  border-radius: 3px;
  white-space: nowrap;
}

.herb-tag.sedative {
  background-color: var(--tag-sedative-bg);
  color: var(--tag-sedative-text);
}

.herb-tag.immune {
  background-color: var(--tag-immune-bg);
  color: var(--tag-immune-text);
}

.herb-tag.antiviral {
  background-color: var(--tag-antiviral-bg);
  color: var(--tag-antiviral-text);
}

.herb-tag.tonic {
  background-color: var(--tag-tonic-bg);
  color: var(--tag-tonic-text);
}

.card-footer {
  background-color: var(--footer-bg);
  color: var(--footer-text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
  border-top: 2px solid var(--accent-gold);
  gap: 12px;
}

.dosage-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.dosage-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--accent-gold);
}

.dosage-val {
  font-size: 13px;
  font-weight: 700;
  color: var(--footer-text);
}

.warning-block {
  display: flex;
  align-items: center;
  gap: 5px;
  background-color: rgba(212, 131, 26, 0.15);
  border: 1px solid var(--warn-color);
  border-radius: 4px;
  padding: 4px 9px;
  flex: 1;
  justify-content: center;
}

.warn-icon {
  font-size: 13px;
  color: var(--warn-color);
}

.warn-text {
  font-size: 11px;
  font-weight: 600;
  color: var(--warn-color);
}

.potency-block {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}

.potency-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--accent-gold);
}

.potency-bars {
  display: flex;
  gap: 3px;
  align-items: flex-end;
}

.bar {
  display: block;
  width: 10px;
  border-radius: 2px;
  height: 14px;
  background-color: var(--bar-empty);
  opacity: 0.4;
}

.bar.filled {
  background-color: var(--bar-filled);
  opacity: 1;
}
